/* DEAD SECTOR service worker — GENERATED by src/pwa.py. Do not edit by hand.
 *
 * Strategy
 *   install  : precache the entire app shell, icons, favicon & install screenshots.
 *   activate : delete every cache that isn't this build (name embeds a hash).
 *   navigate : network-first, fall back to the cached shell -> instant updates
 *              when online AND 100% playable offline with zero network.
 *   assets   : cache-first, filling the cache as you go.
 */
const BUILD   = 'e0798677b7';
const VERSION = 'dead-sector-' + BUILD;
const SCOPE   = self.registration.scope;
const SHELL   = new URL('./index.html', SCOPE).href;
const CORE = [
  new URL('./', SCOPE).href,
  SHELL,
  new URL('./favicon.ico', SCOPE).href,
  new URL('./manifest.webmanifest', SCOPE).href,
  new URL('./icons/icon-192.png', SCOPE).href,
  new URL('./icons/icon-512.png', SCOPE).href,
  new URL('./icons/icon-maskable-192.png', SCOPE).href,
  new URL('./icons/icon-maskable-512.png', SCOPE).href,
  new URL('./icons/apple-touch-icon-180.png', SCOPE).href,
  new URL('./icons/favicon-32.png', SCOPE).href,
  new URL('./assets/screenshots/gameplay_hud.png', SCOPE).href,
  new URL('./assets/screenshots/character_select.png', SCOPE).href,
  new URL('./assets/screenshots/mobile_touch_controls.png', SCOPE).href
];

self.addEventListener('install', (e) => {
  self.skipWaiting();
  e.waitUntil((async () => {
    const c = await caches.open(VERSION);
    await Promise.all(CORE.map((u) =>
      c.add(new Request(u, { cache: 'reload' })).catch(() => {})));
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k !== VERSION).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;   // never touch third parties

  // --- page loads: try the network, fall back to the cached game -------------
  if (req.mode === 'navigate') {
    e.respondWith((async () => {
      try {
        const fresh = await fetch(req);
        if (fresh && fresh.ok) {
          const c = await caches.open(VERSION);
          c.put(SHELL, fresh.clone());
        }
        return fresh;
      } catch (err) {
        const c = await caches.open(VERSION);
        return (await c.match(SHELL)) || (await c.match(SCOPE)) ||
               new Response('<h1>OFFLINE</h1>', { status: 503, headers: { 'Content-Type': 'text/html' } });
      }
    })());
    return;
  }

  // --- everything else: cache-first -----------------------------------------
  e.respondWith((async () => {
    const c = await caches.open(VERSION);
    const hit = await c.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res && res.ok && res.type === 'basic') c.put(req, res.clone());
      return res;
    } catch (err) {
      return new Response('', { status: 504 });
    }
  })());
});

// the page asks for this when it finds a waiting worker (the "NEW BUILD" toast)
self.addEventListener('message', (e) => {
  if (e.data === 'SKIP_WAITING' || (e.data && e.data.type === 'SKIP_WAITING')) {
    self.skipWaiting();
  }
});
